def icon(name='arrow'):
 paths={'arrow':'M4 12h16m-6-6 6 6-6 6','external':'M6 18 18 6M6 6h12v12','menu':'M4 8h16M4 16h16','search':'m20 20-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0','back':'M20 12H4m6-6-6 6 6 6'}
 return f'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths[name]}"/></svg>'

def button(text,url,style='primary',arrow=True):return f'<a class="button {style}" href="{e(url,quote=True)}">{e(text)}{icon() if arrow else ""}</a>'

def header(current='',prefix=''):
 links=''.join(f'<a href="{prefix}{file}"'+(' aria-current="page"' if current==name else '')+f'>{name}</a>' for name,file in [('Products','products.html'),('Games','games.html'),('TV Apps','tv.html'),('About','about.html')])
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-inner"><a class="wordmark" href="{prefix}index.html" aria-label="Majd Hijazin home">Majd Hijazin<span>.</span></a><nav class="nav-links" id="main-nav" aria-label="Main navigation">{links}</nav><div class="header-cta">{button("Let's talk",prefix+'contact.html','dark small')}</div><button class="menu-toggle" aria-label="Open menu" aria-controls="main-nav" aria-expanded="false">{icon('menu')}</button></div></header>'''

def footer(prefix=''):
 return f'''<footer class="site-footer"><div class="wrap"><div class="footer-top"><a class="wordmark" href="{prefix}index.html">Majd Hijazin<span>.</span></a><nav class="footer-links" aria-label="Footer"><a href="{prefix}products.html">Products</a><a href="{prefix}games.html">Games</a><a href="{prefix}tv.html">TV Apps</a><a href="https://www.linkedin.com/in/majd-hijazin/" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="https://github.com/Hijazin" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav></div><div class="footer-bottom"><span>© 2026 Majd Hijazin · Amman, Jordan</span><span>Ideas, built with intent. &nbsp; <a href="{prefix}privacy.html">Privacy</a></span></div></div></footer>'''

def collab(prefix='',title='Have something<br>worth building?',text='A product idea, a growth challenge, or a partnership. Let’s find the useful next step.'):
 return f'<section class="wrap collab"><div><div class="eyebrow blue-text">Work with me</div><h2>{title}</h2><p>{text}</p></div>{button("Let's talk",prefix+"contact.html")}</section>'

def page(file,title,body,current='',description='',prefix=''):
 description=description or 'Independent products, browser games and TV experiences by Majd Hijazin. Explore the work, meet the builder, or start a conversation.'
 canonical=ORIGIN+file
 social_image=next((p['image'] for p in PRODUCTS+GAMES+TV if file=='projects/'+p['id']+'.html'),'architecture.png')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} · Majd Hijazin</title><meta name="description" content="{e(description,quote=True)}"><meta name="theme-color" content="#F5F3EE"><link rel="canonical" href="{canonical}"><link rel="icon" href="{prefix}studio-assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="{prefix}studio-assets/google-sans-400.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{prefix}studio-assets/site.css"><meta property="og:title" content="{e(title)} · Majd Hijazin"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}studio-assets/{social_image}"><meta name="twitter:card" content="summary_large_image"><script src="{prefix}studio-assets/site.js" defer></script><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'Person','name':'Majd Hijazin','url':ORIGIN,'jobTitle':'Marketing strategist and product builder','sameAs':['https://github.com/Hijazin','https://www.linkedin.com/in/majd-hijazin/']})}</script></head><body>{header(current,prefix)}{body}{footer(prefix)}</body></html>'''
 target=OUT/file;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)

def tv_preview(prefix='',large=False):
 return f'<div class="tv-preview tv-real-preview"><img src="{prefix}{ASSETS}agent-wall-screen.png" alt="Agent Wall’s original TV workspace" loading="lazy"><span class="tv-real-label">The TV collection <i>Android TV · Google TV · Fire TV exploration</i></span></div>'

def art(p,prefix='',detail=False):
 is_tv=p['kind']=='TV app';is_game=p['kind']=='Game';img=p.get('image');color=p.get('color','lavender')
 cls=('detail-visual '+('tv-visual ' if is_tv else 'game-visual ' if is_game else '')) if detail else 'project-art '+('screen-art ' if is_tv else 'game-art ' if is_game else '')
 if img:content=f'<img src="{prefix}{ASSETS}{img}" alt="{e(p["name"])} '+('application interface' if is_tv else 'gameplay' if is_game else 'project preview')+'" loading="lazy"'+(' width="1024" height="1024"' if is_tv else '')+'>'
 else:content=f'<span class="monogram" aria-hidden="true">{e(p.get("mark",p["name"][:2]))}</span>'
 if not img:content+=f'<span class="art-name">{e(p["name"])}</span>' if not detail else ''
 return f'<div class="{cls}{color}">{content}</div>'

def status(p):return f'<span class="status {"live" if p["status"] in ["Live","Playable"] else ""}">{e(p["status"])}</span>'

def card(p,prefix=''):
 search=e(' '.join([p['name'],p['description'],p['category'],p['status']]),quote=True)
 return f'<article class="project-card" data-project="{p["id"]}" data-category="{e(p["category"],quote=True)}" data-search="{search}"><a href="{prefix}projects/{p["id"]}.html" aria-label="Explore {e(p["name"],quote=True)}">{art(p,prefix)}<div class="project-meta"><h2>{e(p["name"])}</h2>{status(p)}</div><p>{e(p["description"])}</p><div class="project-category">{e(p["category"])} &nbsp; {icon('external') if False else '↗'}</div></a></article>'

def toolbar(items,categories):
 filters=''.join(f'<button class="filter" data-filter="{e(c,quote=True)}" aria-pressed="{str(c=="All").lower()}">{e(c)}</button>' for c in ['All']+categories)
 return f'<div class="catalogue-toolbar"><div class="filters" role="group" aria-label="Filter projects">{filters}</div><div class="search-box">{icon("search")}<label class="sr-only" for="project-search">Search projects</label><input id="project-search" type="search" placeholder="Search the collection" data-search autocomplete="off"></div></div><div class="results-line" data-result-count role="status">{len(items)} projects</div><noscript><p class="no-js-note">All projects are shown below. Search and filters need JavaScript.</p></noscript>'

def catalogue(items):return '<div class="catalogue-grid">'+''.join(card(p) for p in items)+'</div><div class="empty-state" data-empty hidden><h2>No projects found.</h2><p>Try a different name or explore the whole collection.</p><button class="button outline" data-reset>Clear filters</button></div>'

def page_head(kicker,title,description):return f'<div class="page-head"><div class="eyebrow blue-text">{kicker}</div><h1>{title}</h1><p>{description}</p></div>'

