for p in PRODUCTS+GAMES+TV:
 prefix='../';is_tv=p['kind']=='TV app';is_game=p['kind']=='Game';back='tv.html' if is_tv else 'games.html' if is_game else 'products.html'
 interest='TV apps & licensing' if is_tv else 'Games & interactive experiences' if is_game else 'Product partnership'
 enquiry=f'../contact.html?interest={quote(interest)}&project={quote(p["name"])}'
