 collection=TV if is_tv else GAMES if is_game else PRODUCTS
 related=[q for q in collection if q['id']!=p['id'] and q['category']==p['category']][:2]
 if len(related)<2: related=[q for q in collection if q['id']!=p['id']][:2]
 more=''.join(card(q,'../') for q in related)
 note=p.get('image_note','Original gameplay capture' if is_game else 'Original website or product interface')
